SELECT



    p.is_deleted = 0

        AND (p.product_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%'))


        AND p.category_id = #{q.categoryId}


        AND p.brand_id = #{q.brandId}



        AND p.id IN
        #{productId}



        AND p.user_id = #{q.currentUserId}


        AND p.status = #{q.status}


        AND p.create_time >= #{q.beginTime}


        AND p.create_time <= #{q.endTime}



ORDER BY p.status DESC, p.sort ASC, p.id DESC

SELECT


WHERE p.is_deleted = 0 AND p.status = 1

    AND (p.product_name LIKE CONCAT('%', #{q.keyword}, '%')
    OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%'))



    AND p.category_id IN

        #{cid}




    AND p.carousel_enable = #{q.carouselEnable}



    AND p.store_id = #{q.storeId}



    AND p.brand_id = #{q.brandId}



    AND p.cultural_enable = #{q.culturalEnable}


ORDER BY p.sort ASC, p.id DESC
